INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-fusion-de-las-burbujas-y-palomitas', 'La Fusión de las Burbujas y Palomitas', 'Dinámica de integración progresiva y desinhibición rítmica donde los scouts flotan y saltan fusionándose hasta formar un solo grupo unido.', '<h2>📜 Descripción de La Fusión de las Burbujas y Palomitas</h2>
<p><b>La Fusión de las Burbujas y Palomitas</b> es una dinámica scout de contacto cooperativo, distensión afectiva y cohesión de grupo. En la primera fase (<i>Las Burbujas</i>), los participantes flotan suavemente por la sala con movimientos etéreos; al rozar a un compañero, se enlazan del brazo formando una masa de aire cada vez más grande hasta unificar a toda la unidad. En la segunda fase (<i>Las Palomitas de Maíz</i>), los scouts saltan y explotan con energía rítmica; cada vez que dos palomitas se tocan, se adhieren de la mano y continúan saltando juntas hasta crear una gigantesca bola de palomitas en movimiento.</p>
<p>Esta dinámica desarrolla la empatía no verbal, el desfogue de energías y el sentido de pertenencia en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega La Fusión de las Burbujas y Palomitas?</h2>
<p>Para llevar a cabo la dinámica con alegría y dinamismo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Fase 1 - Las Burbujas Flotantes:</b> Los scouts se desplazan en silencio imitando burbujas jabonosas de jabón. Al tocar suavemente a un compañero, se toman de la mano y continúan flotando juntos atrayendo a nuevas burbujas hasta unificar al grupo entero.</li>
  <li><b>Transición del Calor:</b> El dirigente anuncia: <i>''¡Aumenta la temperatura en la olla de campamento!''</i> y los participantes pasan al modo palomitas de maíz.</li>
  <li><b>Fase 2 - La Explosión de las Palomitas:</b> Los beneficiarios saltan libremente haciendo ruidos de explosión festivos (<i>''¡Pop, pop!''</i>). Al hacer contacto con otro scout, se enlazan firmemente y siguen saltando al unísono.</li>
  <li><b>La Mega Bola de Maíz:</b> Todos los subgrupos se fusionan progresivamente hasta formar una enorme masa de palomitas que se desplaza cantando por el campo.</li>
  <li><b>Reflexión de Cierre:</b> Se realiza un círculo de unidad con los pañolines donde los beneficiarios comparten la sensación de acoger a cada hermano scout.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Fusión de las Burbujas y Palomitas</h2>
<p>La actividad premia el entusiasmo inclusivo y el ritmo colectivo en el Tally:</p>
<ul>
  <li><b>Fusión Más Inclusiva:</b> Otorgar 5 puntos a la unidad que integre a todos sus miembros sin dejar a nadie aislado en el salto.</li>
  <li><b>Entusiasmo Rítmico:</b> Otorgar 3 puntos al grupo que demuestre la mayor energía y alegría durante la fase de palomitas.</li>
  <li><b>Fluidez de Movimiento:</b> Otorgar 3 puntos a la seisena o patrulla que navegue la fase de burbujas con mayor delicadeza.</li>
</ul>', '/uploads/la-fusion-de-las-burbujas-y-palomitas.webp', 'publicado', '{"areas": ["afectividad", "sociabilidad", "corporalidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "15 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Practicar una conducta asertiva y actitud afectuosa", "Crear un clima de pertenencia e integración", "Desfogue de energías y motricidad rítmica", "Fomentar la comunicación en el grupo"], "justificacion_areas": "La Fusión de las Burbujas y Palomitas potencia la afectividad al brindar un espacio de desfogue emocional festivo y abrazo fraternal que disuelve inhibiciones. Fortalece la sociabilidad al afianzar el sentido de pertenencia y la acogida inmediata hacia cada compañero. Desarrolla la corporalidad al ejercitar la motricidad rítmica del salto y el desplazamiento fluido.", "variaciones": "<b>Fusión a Ciegas:</b> Realizar la fase de burbujas con los ojos vendados o cerrados, guiándose únicamente por el tacto suave de las manos.<br><b>Burbujas por Pañolines:</b> Enlazarse únicamente sosteniendo el pañolín del compañero para mantener distancias respetuosas.<br><b>El Baile del Maíz Gigante:</b> La gran masa final de palomitas debe realizar una coreografía de campamento improvisada.", "recomendaciones": "Moderar la intensidad de los saltos en la fase de palomitas para evitar pisotones accidentales. Mantener una superficie acolchada o césped despejado. Fomentar la inclusión de los scouts más tímidos.", "objetivos_educativos": [{"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Tratando con cariño y entusiasmo a los lobatos al fusionarnos en el juego."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Expresando mi alegría y acogiendo sin burlas la participación de todos."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Respetando los ritmos de salto y movimiento de las compañeras de la masa de palomitas."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Comunicándome con asertividad y calidez afectiva para mantener el equilibrio del grupo."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Favoreciendo un ambiente de confianza, superando la inhibición personal en la patrulla."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Demostrando afecto y solidaridad fraterna hacia cada hermano scout del grupo."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando las consignas de contacto y fusión progresiva del dirigente."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Integrándome con lealtad a la gran bola de palomitas sin romper el enlace."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando la inclusión plena y el respeto a la integridad física de las pares."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Apoyando con actitud fraterna la consolidación del clima de grupo."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo con honestidad scout las reglas de movimiento y agarre."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Manada", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Disfrutando del salto rítmico y la actividad física vigorosa en la Manada."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Manada", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Desarrollando la agilidad de salto y el control de impulsos motores en grupo."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "unidad": "Compañía", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Coordinando la amortiguación del salto en desplazamientos colectivos."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Exigiendo dinamismo y resistencia física en la fase de palomitas."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "unidad": "Tropa", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Afinando la motricidad rítmica en la navegación de masas de personas."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Perfeccionando la coordinación motriz kinésica en competencias de grupo."}]}'::jsonb, NOW(), NOW(), NULL, NULL
